import { useState } from "react";
export function ConditionalHook({ enabled }: { enabled: boolean }) {
  if (!enabled) return null;
  const [value] = useState(0);
  return <span>{value}</span>;
}

import { useState } from "react";
export function ValidHook({ enabled }: { enabled: boolean }) {
  const [value] = useState(0);
  if (!enabled) return null;
  return <span>{value}</span>;
}

import { useState } from "react";
export function RenderUpdate() {
  const [count, setCount] = useState(0);
  setCount(1);
  return <span>{count}</span>;
}

import { useState } from "react";
export function EventUpdate() {
  const [count, setCount] = useState(0);
  return <button onClick={() => setCount(count + 1)}>{count}</button>;
}

export function Avatar() {
  return <img src="avatar.png" />;
}

export function Logo() {
  return <img src="logo.png" alt="Company logo" />;
}

export function FallbackAvatar() {
  return <img src="avatar.png" />;
}

export function FallbackLogo() {
  return <img src="logo.png" alt="Company logo" />;
}

import { use } from "react";
export function ConditionalUse({ enabled, data }: { enabled: boolean; data: Promise<string> }) {
  if (enabled) return <span>{use(data)}</span>;
  return null;
}

import { use } from "react";
export function LoopUse({ values }: { values: Promise<string>[] }) {
  const items = [];
  for (const value of values) items.push(use(value));
  return <span>{items.join(",")}</span>;
}

import { useActionState } from "react";
export function ActionForm({ save }: { save: (state: string, data: FormData) => Promise<string> }) {
  const [state, action, pending] = useActionState(save, "");
  return <form action={action}><button disabled={pending}>{state}</button></form>;
}

import { useState } from "react";
export function GuardedUpdate({ items }: { items: string[] }) {
  const [previous, setPrevious] = useState(items);
  const [selection, setSelection] = useState<string | null>(null);
  if (items !== previous) { setPrevious(items); setSelection(null); }
  return <span>{selection}</span>;
}

import { useEffect } from "react";
export function MissingDependency({ value }: { value: string }) {
  useEffect(() => { console.log(value); }, []);
  return null;
}

import { useEffect } from "react";
export function CompleteDependencies({ value }: { value: string }) {
  useEffect(() => { console.log(value); }, [value]);
  return null;
}

import { useEffect, useEffectEvent } from "react";
export function Timer({ value }: { value: string }) {
  const onTick = useEffectEvent(() => { console.log(value); });
  useEffect(() => {
    const timer = setInterval(() => onTick(), 1000);
    return () => clearInterval(timer);
  }, []);
  return null;
}

export function RenamedUser({ user }: { user: { name: string } }) {
  user.name = "changed";
  return <span>{user.name}</span>;
}

export function SortedCopy({ items }: { items: string[] }) {
  const sorted = [...items];
  sorted.sort();
  return <span>{sorted.join(",")}</span>;
}

import { useEffect, useState } from "react";
export function DerivedEffect({ value }: { value: string }) {
  const [label, setLabel] = useState("");
  useEffect(() => { setLabel(value.toUpperCase()); }, [value]);
  return <span>{label}</span>;
}

export function DerivedRender({ value }: { value: string }) {
  const label = value.toUpperCase();
  return <span>{label}</span>;
}

import { useRef } from "react";
export function RefRead() {
  const value = useRef(0);
  return <span>{value.current}</span>;
}

import type { Ref } from "react";
export function Input({ ref, label }: { ref?: Ref<HTMLInputElement>; label: string }) {
  return <input ref={ref} aria-label={label} />;
}

import { Fragment, useRef } from "react";
export function FragmentGroup() {
  const groupRef = useRef(null);
  return <Fragment ref={groupRef}><span>A</span><span>B</span></Fragment>;
}
